public class Compiler_getState_TriageGen0Test {

    private Compiler compiler;

    @Before
    public void setUp() {
        compiler = new Compiler();
    }

    @Test
    public void testGetState_ReturnsNewStateWithDefaultValues() {
        // Since we haven't initialized the compiler with specific inputs, 
        // we test that it returns a non-null object and captures current null/default states.
        IntermediateState state = compiler.getState();

        assertNotNull(state);
        assertNull(state.externsRoot);
        assertNull(state.jsRoot);
        assertNull(state.externs);
        assertNull(state.inputs);
        assertNull(state.modules);
        assertNull(state.typeRegistry);
        // normalized is a boolean, default should be false
        assertEquals(false, state.normalized);
    }

    @Test
    public void testGetState_ReflectsInitializedFields() {
        // Setup dependencies
        CompilerOptions options = new CompilerOptions();
        JSSourceFile extern = JSSourceFile.parse("extern.js", "function a() {}");
        JSSourceFile input = JSSourceFile.parse("input.js", "var x = 1;");

        // Mock PassConfig to avoid complex initialization of the internal pass pipeline
        PassConfig mockPassConfig = mock(PassConfig.class);
        IntermediateState mockIntermediateState = new IntermediateState();
        when(mockPassConfig.getIntermediateState()).thenReturn(mockIntermediateState);

        compiler.init(new JSSourceFile[]{extern}, new JSSourceFile[]{input}, options);
        compiler.setPassConfig(mockPassConfig);

        // Trigger normalization to test the 'normalized' field coverage
        compiler.normalize();

        // Execute
        IntermediateState state = compiler.getState();

        // Verify
        assertNotNull(state);
        assertEquals(extern, state.externsRoot); // Note: in init, externs[0] becomes externsRoot logic varies by implementation, 
                                                 // but we check if the state object captures the compiler's current fields.
        assertEquals(input, state.jsRoot);
        assertEquals(mockIntermediateState, state.passConfigState);
        assertTrue(state.normalized);
    }

    @Test
    public void testGetState_WithModules() {
        CompilerOptions options = new CompilerOptions();
        JSModule module = new JSModule("mod", "var x = 1;");

        // We need to use a spy or a way to set internal fields if they aren't public, 
        // but based on the provided 'getState' code, we can use init(externs, modules, options)
        compiler.init(new JSSourceFile[0], new JSModule[]{module}, options);

        IntermediateState state = compiler.getState();

        assertNotNull(state);
        assertEquals(module, state.modules[0]);
    }

    @Test
    public void testGetState_ConsistencyWithSetState() {
        // Test that setting a state and then getting it (if provided) behaves as expected
        // though the method 'getState' always creates a NEW IntermediateState object
        // based on the current internal fields of the compiler.

        IntermediateState manualState = new IntermediateState();
        manualState.normalized = true;
        // Note: setState is provided in the signature, so we can use it to influence subsequent getState()
        // However, the provided getState() code uses internal fields like 'externsRoot', not the 'state' object itself.
        // This implies setState must populate those internal fields.

        compiler.setState(manualState);

        // If setState simply assigns the object, getState() will create a NEW object 
        // but copy the values from the compiler's internal fields.
        IntermediateState newState = compiler.getState();

        assertNotNull(newState);
        // Since setState was called, the internal fields should reflect manualState if the implementation 
        // of setState is a standard field assignment.
        assertEquals(manualState.normalized, newState.normalized);
    }
}
